  1	import java.util.Arrays;
  2	import java.util.NoSuchElementException;
  3	
  4	public final class MinHeap implements LegacyMinHeapApi {
  5	    private static final int DEFAULT_CAPACITY = 10;
  6	
  7	    private int[] elements;
  8	    private int size;
  9	
 10	    public MinHeap() {
 11	        this(new int[DEFAULT_CAPACITY], 0, false);
 12	    }
 13	
 14	    public MinHeap(int initialCapacity) {
 15	        this(new int[validateInitialCapacity(initialCapacity)], 0, false);
 16	    }
 17	
 18	    public MinHeap(int[] values) {
 19	        this(copyInput(values), values.length, true);
 20	    }
 21	
 22	    public static MinHeap from(int... values) {
 23	        return new MinHeap(values);
 24	    }
 25	
 26	    public static MinHeap copyOf(IntHeap other) {
 27	        if (other == null) {
 28	            throw new IllegalArgumentException("other heap must not be null");
 29	        }
 30	
 31	        return new MinHeap(other.toArray());
 32	    }
 33	
 34	    private MinHeap(int[] elements, int size, boolean needsHeapify) {
 35	        this.elements = elements;
 36	        this.size = size;
 37	        if (needsHeapify) {
 38	            rebuildHeap();
 39	        }
 40	    }
 41	
 42	    @Override
 43	    public boolean offer(int value) {
 44	        ensureCapacity(size + 1);
 45	        elements[size] = value;
 46	        siftUp(size);
 47	        size++;
 48	        return true;
 49	    }
 50	
 51	    @Override
 52	    public void addAll(int... values) {
 53	        if (values == null) {
 54	            throw new IllegalArgumentException("values must not be null");
 55	        }
 56	
 57	        if (values.length == 0) {
 58	            return;
 59	        }
 60	
 61	        int originalSize = size;
 62	        ensureCapacity(originalSize + values.length);
 63	        System.arraycopy(values, 0, elements, originalSize, values.length);
 64	        size += values.length;
 65	        rebuildHeap();
 66	    }
 67	
 68	    @Override
 69	    public int peek() {
 70	        ensureNotEmpty();
 71	        return elements[0];
 72	    }
 73	
 74	    @Override
 75	    public int removeMin() {
 76	        ensureNotEmpty();
 77	        return removeAt(0);
 78	    }
 79	
 80	    @Override
 81	    public int replaceMin(int value) {
 82	        ensureNotEmpty();
 83	        int previousMin = elements[0];
 84	        elements[0] = value;
 85	        siftDown(0);
 86	        return previousMin;
 87	    }
 88	
 89	    @Override
 90	    public int removeAt(int index) {
 91	        validateOccupiedIndex(index);
 92	
 93	        int removedValue = elements[index];
 94	        int lastIndex = size - 1;
 95	        int lastValue = elements[lastIndex];
 96	        elements[lastIndex] = 0;
 97	        size--;
 98	        if (index == lastIndex) {
 99	            return removedValue;
100	        }
101	
102	        elements[index] = lastValue;
103	        restoreHeapAt(index);
104	        return removedValue;
105	    }
106	
107	    @Override
108	    public void updateValue(int index, int newValue) {
109	        validateOccupiedIndex(index);
110	
111	        int currentValue = elements[index];
112	        elements[index] = newValue;
113	        if (newValue < currentValue) {
114	            siftUp(index);
115	            return;
116	        }
117	
118	        if (newValue > currentValue) {
119	            siftDown(index);
120	        }
121	    }
122	
123	    @Override
124	    public void clear() {
125	        Arrays.fill(elements, 0, size, 0);
126	        size = 0;
127	    }
128	
129	    @Override
130	    public boolean isEmpty() {
131	        return size == 0;
132	    }
133	
134	    @Override
135	    public int size() {
136	        return size;
137	    }
138	
139	    @Override
140	    public int capacity() {
141	        return elements.length;
142	    }
143	
144	    @Override
145	    public int valueAt(int index) {
146	        validateOccupiedIndex(index);
147	        return elements[index];
148	    }
149	
150	    @Override
151	    public int[] toArray() {
152	        return Arrays.copyOf(elements, size);
153	    }
154	
155	    private void rebuildHeap() {
156	        for (int index = parentIndex(size - 1); index >= 0; index--) {
157	            siftDown(index);
158	        }
159	    }
160	
161	    private void ensureCapacity(int requiredCapacity) {
162	        if (requiredCapacity <= elements.length) {
163	            return;
164	        }
165	
166	        int newCapacity = elements.length == 0 ? 1 : elements.length;
167	        while (newCapacity < requiredCapacity) {
168	            newCapacity *= 2;
169	        }
170	
171	        elements = Arrays.copyOf(elements, newCapacity);
172	    }
173	
174	    private void siftUp(int index) {
175	        while (index > 0) {
176	            int parentIndex = parentIndex(index);
177	            if (elements[parentIndex] <= elements[index]) {
178	                return;
179	            }
180	
181	            swap(index, parentIndex);
182	            index = parentIndex;
183	        }
184	    }
185	
186	    private void siftDown(int index) {
187	        while (true) {
188	            int leftChildIndex = leftChildIndex(index);
189	            int rightChildIndex = rightChildIndex(index);
190	            int smallestIndex = index;
191	
192	            if (leftChildIndex < size && elements[leftChildIndex] < elements[smallestIndex]) {
193	                smallestIndex = leftChildIndex;
194	            }
195	
196	            if (rightChildIndex < size && elements[rightChildIndex] < elements[smallestIndex]) {
197	                smallestIndex = rightChildIndex;
198	            }
199	
200	            if (smallestIndex == index) {
201	                return;
202	            }
203	
204	            swap(index, smallestIndex);
205	            index = smallestIndex;
206	        }
207	    }
208	
209	    private void restoreHeapAt(int index) {
210	        if (index > 0 && elements[index] < elements[parentIndex(index)]) {
211	            siftUp(index);
212	            return;
213	        }
214	
215	        siftDown(index);
216	    }
217	
218	    private void swap(int firstIndex, int secondIndex) {
219	        int temp = elements[firstIndex];
220	        elements[firstIndex] = elements[secondIndex];
221	        elements[secondIndex] = temp;
222	    }
223	
224	    private void ensureNotEmpty() {
225	        if (isEmpty()) {
226	            throw new NoSuchElementException("heap is empty");
227	        }
228	    }
229	
230	    private void validateOccupiedIndex(int index) {
231	        if (index < 0 || index >= size) {
232	            throw new IndexOutOfBoundsException(
233	                "index " + index + " is outside heap size " + size
234	            );
235	        }
236	    }
237	
238	    private int parentIndex(int index) {
239	        return (index - 1) / 2;
240	    }
241	
242	    private int leftChildIndex(int index) {
243	        return index * 2 + 1;
244	    }
245	
246	    private int rightChildIndex(int index) {
247	        return index * 2 + 2;
248	    }
249	
250	    private static int validateInitialCapacity(int initialCapacity) {
251	        if (initialCapacity < 0) {
252	            throw new IllegalArgumentException("initial capacity must be non-negative");
253	        }
254	
255	        return initialCapacity;
256	    }
257	
258	    private static int[] copyInput(int[] values) {
259	        if (values == null) {
260	            throw new IllegalArgumentException("values must not be null");
261	        }
262	
263	        return Arrays.copyOf(values, values.length);
264	    }
265	}
